import catalog from "./gallery-supplements.json";

export type GallerySupplement = {
  id: string;
  venue: "iccv" | "eccv" | "emnlp";
  year: number;
  title: string;
  authors: string[];
  pattern: "conceptual" | "framework" | "pipeline" | "architecture" | "teaser" | "taxonomy" | "results" | "comparison";
  image: string;
  paper: string;
  source: "official-proceedings";
  w: number;
  h: number;
  page: number;
};

// Generated by scripts/build-gallery-supplements.py from official proceedings.
// The version is a content digest, so Vite Fast Refresh reloads the catalogue
// when a new extraction batch lands instead of preserving stale component data.
export const GALLERY_SUPPLEMENT_VERSION = catalog.version;
export const GALLERY_SUPPLEMENTS = catalog.figures as GallerySupplement[];
